PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kg: <https://moosedev.dev/kg/>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT ?ad ?title ?desc ?status WHERE {
  ?ad rdf:type kg:ArchitecturalDecision ;
      rdfs:label ?title ;
      kg:hasLifecycleStatus ?status .
  FILTER(LCASE(STR(?status)) = "accepted")
  OPTIONAL { ?ad kg:hasDescription ?desc }
  FILTER NOT EXISTS { ?ad kg:hasRationale ?r1 }
  FILTER NOT EXISTS { ?ad kg:isMotivatedBy ?r2 }
  FILTER NOT EXISTS { ?ad kg:motivatedBy ?r3 }
  FILTER NOT EXISTS { ?ad bfo:0000176 ?r4 }
}
ORDER BY LCASE(STR(?title))

