/bin/zsh -lc "awk '
function unquote(s,   t) {
  if (s ~ /"'^"/) {
    sub(/''^"/, "", s)
    sub(/"('"\\"'^'"\\"'^<[''^>]+>|@[A-Za-z0-9-]+)?$/, "", s)
  }
  return s
}
BEGIN {
  proj = "<https://moosedev.dev/kg/project>"
  adtype = "<https://trivyn.io/ontologies/software/architecture/domain/ArchitecturalDecision>"
  statusp = "<https://trivyn.io/ontologies/software/architecture/domain/hasLifecycleStatus>"
  rationalep = "<https://trivyn.io/ontologies/software/architecture/domain/hasRationale>"
  bfo = "<http://purl.obolibrary.org/obo/BFO_0000176>"
  labelp = "<http://www.w3.org/2000/01/rdf-schema#label>"
  titlep = "<https://trivyn.io/ontologies/software/architecture/domain/hasTitle>"
}
{
  if (match($0, /''^<([''^>]*)> <([''^>]*)> (.*) <https:'"\\/\\/moosedev\\.dev\\/kg\\/project> \\."'$/, m)) {
    s = m[1]
    p = "<" m[2] ">"
    o = m[3]
    if (p == "<http://www.w3.org/1999/02/22-rdf-syntax-ns#type>" && o == adtype) {
      is_ad[s] = 1
    } else if (p == statusp) {
      status[s] = unquote(o)
    } else if (p == rationalep || p == bfo) {
      has_rationale[s] = 1
    } else if (p == labelp || p == titlep) {
      title[s] = unquote(o)
    }
  }
}
END {
  count = 0
  for (s in is_ad) {
    if (tolower(status[s]) == "accepted" && !has_rationale[s]) {
      count++
      print title[s] "'"\\t\" s
    }
  }
}
